  "/{min} to /{max}; empty uses the pool's default (/{def}).": "/{min} đến /{max}; để trống sẽ dùng mặc định của pool (/{def}).",
  "/64 blocks each project may allocate. Empty = no limit.": "Số khối /64 mỗi dự án được cấp. Để trống = không giới hạn.",
