  "; other interfaces use their own)": "; các interface khác dùng nhóm riêng)",
  "; the zone {availability_zone} disappears if no other aggregate has it": "; vùng {availability_zone} sẽ biến mất nếu không aggregate nào khác có nó",
  "<is> True": "<is> True",
  "= {v} Mbps": "= {v} Mbps",
  "A cloud-init script or #cloud-config document, run on first boot. See the": "Một script cloud-init hoặc tài liệu #cloud-config, chạy ở lần khởi động đầu tiên. Xem",
  "A cookie your application sets": "Cookie do ứng dụng của bạn đặt",
  "A cookie's value": "Giá trị của một cookie",
  "A delete failed": "Xóa thất bại",
  "a device": "một thiết bị",
  "A field of the client certificate's DN, e.g. CN": "Một trường trong DN của chứng chỉ client, ví dụ CN",
  "A flavor is what users pick; its profile holds the provider settings (topology, compute flavor…).": "Flavor là thứ người dùng chọn; profile của nó chứa cài đặt của provider (topology, compute flavor…).",
  "A health monitor belongs to a pool.": "Health monitor thuộc về một pool.",
  "A listener accepts connections on one protocol and port of the VIP and hands them to its default pool (or to an L7 policy's pool).": "Listener nhận kết nối trên một giao thức và port của VIP rồi chuyển chúng tới pool mặc định của nó (hoặc tới pool của một L7 policy).",
  "A listener that is down stops accepting connections.": "Listener ở trạng thái down sẽ ngừng nhận kết nối.",
  "A load balancer that is down stops serving every listener.": "Load balancer bị tắt sẽ ngừng phục vụ mọi listener.",
  "A member is marked down after “retries down” failed checks and back up after “retries up” passed ones. The timeout can't be longer than the interval.": "Thành viên bị đánh dấu down sau “số lần thử down” lần kiểm tra thất bại và up trở lại sau “số lần thử up” lần kiểm tra thành công. Thời gian chờ không được dài hơn khoảng thời gian kiểm tra.",
  "A member that is down gets no traffic.": "Thành viên ở trạng thái down sẽ không nhận lưu lượng.",
  "A member with this address and port is already in the pool.": "Một thành viên với địa chỉ và port này đã có trong pool.",
  "A network can be served by several DHCP agents.": "Một mạng có thể được phục vụ bởi nhiều DHCP agent.",
  "A network that is down passes no traffic.": "Mạng ở trạng thái down không truyền lưu lượng.",
  "A network's policy covers all its ports except those with a policy of their own.": "Chính sách của mạng áp dụng cho mọi port của nó, trừ các port có chính sách riêng.",
  "A number is required": "Cần nhập một số",
  "A password or passphrase": "Mật khẩu hoặc passphrase",
  "A payload can be stored only once; Barbican never changes it afterwards.": "Payload chỉ có thể lưu một lần; Barbican không bao giờ thay đổi nó sau đó.",
  "A policy without rules never matches.": "Policy không có quy tắc sẽ không bao giờ khớp.",
  "A pool is a group of members that share a protocol, a balancing algorithm and an optional health monitor.": "Pool là một nhóm thành viên dùng chung giao thức, thuật toán cân bằng tải và một health monitor (tùy chọn).",
  "A pool is created together with a listener; add pools later from the load balancer's page.": "Pool được tạo cùng với listener; thêm pool sau từ trang của load balancer.",
  "A pool needs at least one prefix; Neutron will refuse to remove them all.": "Pool cần ít nhất một tiền tố; Neutron sẽ từ chối gỡ tất cả.",
  "A project": "Một dự án",
  "A request header's value": "Giá trị của một header trong request",
  "A router normally lives on one L3 agent (two or more for HA).": "Một router thường nằm trên một L3 agent (hai hoặc nhiều hơn với HA).",
  "A router that is down forwards no traffic.": "Router ở trạng thái down sẽ không chuyển tiếp lưu lượng.",
  "A routing domain: Neutron routers forward between subnets of pools in the same scope without NAT, and never route between different scopes.": "Một miền định tuyến: router của Neutron chuyển tiếp giữa các subnet của pool trong cùng scope không qua NAT, và không bao giờ định tuyến giữa các scope khác nhau.",
  "A soft reboot asks the guest OS to restart.": "Khởi động lại mềm yêu cầu hệ điều hành guest khởi động lại.",
  "A temporary URL works without signing in, for anyone who has it, until it expires.": "URL tạm thời hoạt động mà không cần đăng nhập, cho bất kỳ ai có nó, cho đến khi hết hạn.",
  "A TERMINATED_HTTPS listener needs a certificate": "Listener TERMINATED_HTTPS cần có chứng chỉ",
  "A trunk that is down can't have sub-ports added or removed.": "Không thể thêm hoặc gỡ subport khi trunk đang ở trạng thái down.",
  "a volume": "volume",
  "A {size} GiB volume of the default type is created.": "Một volume {size} GiB thuộc loại mặc định sẽ được tạo.",
  "Accept": "Chấp nhận",
  "Accept shared images?": "Chấp nhận các image được chia sẻ?",
