  "ci-deploy": "ci-deploy",
  "Cinder copies the data to the chosen pool and switches the volume over; its ID stays the same. To change the volume type at the same time, use “Change volume type” with migration instead.": "Cinder sao chép dữ liệu sang pool đã chọn rồi chuyển volume sang đó; ID của volume giữ nguyên. Để đồng thời đổi loại volume, hãy dùng “Đổi loại volume” kèm di chuyển.",
  "Cinder copies the volume's data into a new Glance image. Large volumes take a while.": "Cinder sao chép dữ liệu của volume vào một image Glance mới. Volume lớn sẽ mất một lúc.",
  "Cinder creates a new volume for every volume of the source, with the same types.": "Cinder tạo một volume mới cho mỗi volume của nguồn, với cùng loại.",
  "Cinder only allows this while no volumes use the type.": "Cinder chỉ cho phép điều này khi không có volume nào dùng loại này.",
  "Cinder refuses while groups of this type exist.": "Cinder từ chối khi vẫn còn nhóm thuộc loại này.",
  "Cinder refuses while volumes still use a type, and the cloud's default type can't be deleted.": "Cinder sẽ từ chối nếu còn volume dùng loại đó, và không thể xóa loại mặc định của cloud.",
  "Cinder refuses while volumes still use the type, and the cloud's default type can't be deleted.": "Cinder từ chối khi vẫn còn volume dùng loại này, và không thể xóa loại mặc định của cloud.",
  "Cinder refuses while volumes still use the type.": "Cinder sẽ từ chối nếu còn volume dùng loại này.",
  "Cinder sends new work to these services again.": "Cinder sẽ lại gửi công việc mới tới các dịch vụ này.",
  "Cinder sends new work to this service again{v}.": "Cinder sẽ lại gửi công việc mới tới dịch vụ này{v}.",
  "Cinder services and the free capacity the scheduler sees in each pool. Disable a service (e.g. a backend under maintenance) to stop new work going to it.": "Các dịch vụ Cinder và dung lượng trống mà scheduler thấy trong mỗi pool. Tắt một dịch vụ (vd: backend đang bảo trì) để ngừng gửi công việc mới tới nó.",
  "Cinder stops sending new work to these services (new volumes, backups…). Existing volumes keep working.": "Cinder sẽ ngừng gửi công việc mới tới các dịch vụ này (volume mới, bản sao lưu…). Các volume hiện có vẫn hoạt động.",
  "Cinder stops sending new work to this service.": "Cinder sẽ ngừng gửi công việc mới tới dịch vụ này.",
  "Cinder volume": "Volume Cinder",
  "Cinder zones come from storage_availability_zone of each cinder-volume service (see Storage backends).": "Vùng của Cinder lấy từ storage_availability_zone của từng dịch vụ cinder-volume (xem Backend lưu trữ).",
  "Cinder's type for consistency groups migrated to groups. The groups API refuses it, so it isn't offered when creating groups.": "Loại của Cinder dành cho consistency group đã chuyển sang group. API group từ chối loại này, nên nó không được đề xuất khi tạo nhóm.",
