  "Compute usage of every project over the period, from Nova. Open a project for its instances, or download a CSV for billing.": "Mức sử dụng compute của mọi dự án trong khoảng thời gian, lấy từ Nova. Mở một dự án để xem các máy ảo, hoặc tải xuống CSV để tính phí.",
  "Compute usage over the period: instance hours weighted by vCPUs, local disk and RAM, as Nova reports it for billing and capacity planning. Instances that were shut off still count.": "Mức sử dụng compute trong khoảng thời gian: số giờ máy ảo tính theo vCPU, đĩa cục bộ và RAM, do Nova báo cáo để tính phí và lập kế hoạch dung lượng. Máy ảo đã tắt vẫn được tính.",
