  "Every interface has its own security groups (set on the Networks & ports step), so these aren't used.": "Mỗi interface có nhóm bảo mật riêng (đặt ở bước Mạng & port), nên các nhóm này không được dùng.",
  "Every limit set for this project is removed, so the cloud's defaults apply again.": "Mọi giới hạn đặt riêng cho dự án này sẽ bị gỡ bỏ, nên giá trị mặc định của cloud sẽ được áp dụng lại.",
  "Every member of the group gets these roles on the project.": "Mọi thành viên của nhóm đều nhận các vai trò này trên dự án.",
  "Every member on a different host. Launch fails when there are no free hosts left.": "Mỗi thành viên trên một host khác nhau. Khởi tạo sẽ thất bại khi không còn host trống.",
  "Every Neutron port in the cloud: instance interfaces, router and DHCP ports, VIPs and free ports.": "Mọi port Neutron trong cloud: giao diện mạng của máy ảo, port router và DHCP, VIP và port tự do.",
  "Every object in the folder (and its subfolders) is deleted. This can't be undone.": "Mọi object trong thư mục (và các thư mục con) sẽ bị xóa. Thao tác này không thể hoàn tác.",
  "Every project can allocate from it. Can't be undone later.": "Mọi dự án đều có thể cấp phát từ pool. Không thể hoàn tác về sau.",
  "Every project can apply it. To share with chosen projects only, use Sharing (RBAC).": "Mọi dự án đều có thể áp dụng. Để chỉ chia sẻ với các dự án được chọn, hãy dùng Chia sẻ (RBAC).",
