  "How many secrets, containers, orders and consumers each project may create in Barbican. Grey values are the cloud defaults; -1 is unlimited.": "Số lượng secret, container, order và consumer mà mỗi dự án được tạo trong Barbican. Giá trị màu xám là mặc định của cloud; -1 là không giới hạn.",
  "How much of each resource a project may use. Usage shows what the project holds now; Nova and Cinder refuse limits below current usage. -1 means unlimited.": "Lượng tài nguyên mỗi loại mà một dự án được phép dùng. Mức sử dụng cho biết dự án đang giữ bao nhiêu; Nova và Cinder từ chối giới hạn thấp hơn mức sử dụng hiện tại. -1 nghĩa là không giới hạn.",
