  "Instances are destroyed. Root volumes created with “delete on termination” are deleted with them; other attached volumes are detached and kept. This can't be undone.": "Các máy ảo sẽ bị hủy. Volume root được tạo với “delete on termination” sẽ bị xóa cùng; các volume đã gắn khác được gỡ và giữ lại. Không thể hoàn tác.",
  "Instances behind it lose outbound access, and floating IPs through it stop working.": "Máy ảo phía sau sẽ mất truy cập ra ngoài, và các floating IP đi qua nó sẽ ngừng hoạt động.",
