  "It has sub-regions": "Region có region con",
  "It is associated with {typesText}; those types lose their limits.": "Nó đang được gắn với {typesText}; các loại đó sẽ mất giới hạn.",
  "It still holds {n} objects. Swift only deletes empty containers, so Rassvet deletes every object first.": "Container vẫn còn {n} object. Swift chỉ xóa container trống, vì vậy Rassvet sẽ xóa mọi object trước.",
  "It was disabled because:": "Lý do bị tắt:",
  "It's disabled first (Keystone requires that), then deleted. ": "Domain sẽ được tắt trước (Keystone yêu cầu vậy), rồi mới bị xóa. ",
  "It's on the roadmap and will arrive in an upcoming patch.": "Tính năng này đã có trong lộ trình và sẽ có trong bản vá sắp tới.",
  "items": "mục",
  "its parent port": "port cha của nó",
  "Its properties and objects disappear from the metadata editors. Metadata already set on images and instances is kept.": "Các thuộc tính và đối tượng của nó sẽ biến mất khỏi trình sửa metadata. Metadata đã đặt trên image và máy ảo vẫn được giữ lại.",
  "Its protocols are deleted too and federated users can no longer sign in through it. Their shadow users and role assignments stay.": "Các protocol của nó cũng bị xóa và người dùng liên kết không thể đăng nhập qua nó nữa. Shadow user và phân quyền vai trò của họ vẫn được giữ lại.",
  "Its rules are deleted too.": "Các quy tắc của policy cũng bị xóa.",
  "Its running instances keep working; it can't launch new ones with this flavor.": "Các máy ảo đang chạy của dự án vẫn hoạt động; dự án không thể khởi tạo máy ảo mới với flavor này.",
  "Its SAML ECP endpoint.": "Endpoint SAML ECP của nó.",
  "Its secrets are kept.": "Các secret của nó được giữ lại.",
  "Its users can sign in again.": "Người dùng của domain có thể đăng nhập lại.",
  "Its users can't sign in and their tokens stop working until it's enabled again.": "Người dùng của domain không thể đăng nhập và token của họ ngừng hoạt động cho đến khi domain được bật lại.",
  "Its {length} member(s) keep running; ": "{length} thành viên của nhóm vẫn tiếp tục chạy; ",
  "Its {n} member(s) and its health monitor are deleted too. Listeners using it as default pool are left without one.": "{n} thành viên và health monitor của pool cũng bị xóa. Các listener dùng pool này làm pool mặc định sẽ không còn pool mặc định.",
  "jinja template": "template Jinja",
  "JSON schema of the value: title and type (string, integer, number, boolean, array) are required; enum, default, minimum/maximum, pattern and description are optional.": "JSON schema của giá trị: title và type (string, integer, number, boolean, array) là bắt buộc; enum, default, minimum/maximum, pattern và description là tùy chọn.",
  "JSONFilter, e.g. [\">=\", \"$free_ram_mb\", 1024]": "JSONFilter, ví dụ [\">=\", \"$free_ram_mb\", 1024]",
