  "Keep instances together on one host (affinity) or spread them over different hosts (anti-affinity). Instances join a group when they are launched.": "Giữ các máy ảo cùng trên một host (affinity) hoặc phân tán chúng trên nhiều host khác nhau (anti-affinity). Máy ảo tham gia nhóm khi được khởi tạo.",
