  "Keys may contain letters, digits, “-” and “_” only": "Khóa chỉ được chứa chữ cái, chữ số, “-” và “_”",
  "Keys, passwords, certificates and other sensitive data stored by Barbican. Payloads are only shown when you ask for them; services such as Octavia and Cinder read them by reference.": "Khóa, mật khẩu, chứng chỉ và dữ liệu nhạy cảm khác do Barbican lưu trữ. Payload chỉ hiển thị khi bạn yêu cầu; các dịch vụ như Octavia và Cinder đọc chúng qua tham chiếu.",
  "Keystone also needs the matching Apache module (mod_auth_openidc or mod_shib) and the trusted dashboard set in keystone.conf.": "Keystone cũng cần module Apache tương ứng (mod_auth_openidc hoặc mod_shib) và trusted dashboard được đặt trong keystone.conf.",
  "Keystone has no regions registered.": "Keystone chưa đăng ký region nào.",
