  "Let Nova and the image decide": "Để Nova và image quyết định",
  "Let scripts, CI jobs and tools act on a project without using your password. Each credential is bound to the project you create it in and can be revoked at any time.": "Cho phép script, job CI và công cụ thao tác trên một dự án mà không cần mật khẩu của bạn. Mỗi credential gắn với dự án nơi bạn tạo nó và có thể thu hồi bất kỳ lúc nào.",
  "Let the scheduler choose": "Để scheduler chọn",
  "Let users sign in through an external identity provider (Keycloak, Azure AD / Entra ID, ADFS, Okta…) over OpenID Connect or SAML. An identity provider has one protocol per sign-in method; each protocol uses a mapping that turns the provider's claims into a Keystone user and groups (and so roles in projects).": "Cho phép người dùng đăng nhập qua identity provider bên ngoài (Keycloak, Azure AD / Entra ID, ADFS, Okta…) bằng OpenID Connect hoặc SAML. Mỗi identity provider có một protocol cho mỗi phương thức đăng nhập; mỗi protocol dùng một mapping để chuyển claim của provider thành người dùng và nhóm Keystone (và từ đó là vai trò trong dự án).",
  "Letters, digits, dot, dash and underscore, e.g. HN-DC2.": "Chữ cái, chữ số, dấu chấm, gạch ngang và gạch dưới, ví dụ HN-DC2.",
  "Letters, digits, spaces and . _ - @ only.": "Chỉ dùng chữ cái, chữ số, khoảng trắng và . _ - @.",
  "Light": "Sáng",
  "Like pulling the power cord and plugging it back in. Unsaved data in the guest may be lost.": "Giống như rút dây nguồn rồi cắm lại. Dữ liệu chưa lưu trong hệ điều hành khách có thể bị mất.",
  "Limit": "Giới hạn",
  "Limit or guarantee bandwidth and packet rate, or mark traffic with DSCP. Apply a policy to a network (all its ports) or to a single port; a port's own policy wins over its network's.": "Giới hạn hoặc đảm bảo băng thông và tốc độ gói tin, hoặc đánh dấu lưu lượng bằng DSCP. Áp dụng chính sách cho một mạng (tất cả port của nó) hoặc cho một port riêng; chính sách riêng của port được ưu tiên hơn chính sách của mạng.",
