  "Members are the servers that receive the traffic: instances of this cloud, or any address the load balancer can reach.": "Thành viên là các server nhận lưu lượng: máy ảo của cloud này, hoặc bất kỳ địa chỉ nào mà load balancer có thể truy cập.",
  "Members can't sign in to disabled projects or use their resources.": "Thành viên không thể đăng nhập vào dự án đã tắt hoặc dùng tài nguyên của dự án đó.",
  "Members failing the check are taken out of rotation until they pass again.": "Các thành viên không vượt qua kiểm tra sẽ bị loại khỏi vòng phân phối cho đến khi vượt qua lại.",
  "Members keep running; the policy just stops applying to them.": "Các thành viên vẫn tiếp tục chạy; chỉ là chính sách không còn áp dụng cho chúng.",
  "Members lose every role they had only through these groups. The users themselves are kept.": "Thành viên sẽ mất mọi vai trò mà họ chỉ có thông qua các nhóm này. Bản thân người dùng vẫn được giữ lại.",
