  "Neutron agents and the hosts they run on. Disable an agent to stop scheduling new routers or networks to it; move existing ones from its ⋮ menu.": "Các agent Neutron và host mà chúng chạy trên đó. Tắt một agent để ngừng xếp lịch router hoặc mạng mới cho nó; chuyển các mục hiện có từ menu ⋮ của nó.",
