  "Nova services per host. Disable a compute host to stop scheduling new instances to it (maintenance); running instances keep running.": "Các dịch vụ Nova theo từng host. Tắt một compute host để ngừng lập lịch máy ảo mới lên đó (bảo trì); các máy ảo đang chạy vẫn tiếp tục chạy.",
