  "One member per chosen address; members get the instance's name.": "Mỗi địa chỉ được chọn là một thành viên; thành viên được đặt theo tên máy ảo.",
  "One of: {enum}": "Một trong: {enum}",
  "One per line (or comma separated), all IPv4 or all IPv6. Neutron merges adjacent prefixes.": "Mỗi dòng một tiền tố (hoặc cách nhau bằng dấu phẩy), cùng IPv4 hoặc cùng IPv6. Neutron tự gộp các tiền tố liền kề.",
  "One per line (or comma-separated). Empty uses the cloud's default.": "Mỗi dòng một giá trị (hoặc phân tách bằng dấu phẩy). Để trống sẽ dùng mặc định của cloud.",
  "One per line: destination CIDR, next hop. Pushed to instances by DHCP.": "Mỗi dòng một tuyến: CIDR đích, next hop. Được DHCP đẩy xuống máy ảo.",
  "One per line: the OIDC issuer URL or SAML entity ID the provider sends. Keystone matches it against the protocol's remote ID attribute.": "Mỗi dòng một giá trị: URL issuer OIDC hoặc entity ID SAML mà provider gửi. Keystone đối chiếu nó với thuộc tính remote ID của protocol.",
  "One policy (not listed by the cluster).": "Một policy (cluster không liệt kê).",
  "One protocol per way of signing in. Each picks the mapping that turns the provider's claims into Keystone users and groups.": "Mỗi cách đăng nhập một protocol. Mỗi protocol chọn mapping để chuyển claim của provider thành người dùng và nhóm Keystone.",
  "One range per line: start, end. Empty uses the whole subnet.": "Mỗi dòng một dải: bắt đầu, kết thúc. Để trống sẽ dùng toàn bộ subnet.",
