  "Only the description can change; sizes are fixed once a flavor exists (Nova 2.55+).": "Chỉ có thể thay đổi mô tả; kích thước là cố định sau khi flavor được tạo (Nova 2.55+).",
  "Only the name and description can change; delete and recreate it to point at another address.": "Chỉ có thể đổi tên và mô tả; hãy xóa và tạo lại để trỏ tới địa chỉ khác.",
