  "Optional.": "Tùy chọn.",
  "Optional. Allows up to this many members on one host instead of strictly one.": "Tùy chọn. Cho phép tối đa số thành viên này trên một host thay vì chỉ đúng một.",
  "Optional. Also becomes their default project.": "Tùy chọn. Cũng sẽ trở thành dự án mặc định của họ.",
  "Optional. Around 80% of the maximum suits TCP well.": "Tùy chọn. Khoảng 80% mức tối đa phù hợp với TCP.",
  "Optional. Backing up a snapshot gives a consistent copy of an attached volume.": "Tùy chọn. Sao lưu từ snapshot cho bản sao nhất quán của volume đang gắn.",
  "Optional. Barbican refuses to return the payload after this time.": "Tùy chọn. Barbican từ chối trả về payload sau thời điểm này.",
  "Optional. Leave on Default unless the guest needs a specific controller (e.g. no virtio drivers).": "Tùy chọn. Để Mặc định trừ khi hệ điều hành khách cần một bộ điều khiển cụ thể (ví dụ không có driver virtio).",
  "Optional. More subnets can be added later.": "Tùy chọn. Có thể thêm subnet sau.",
  "Optional. Overrides keystone.conf's remote_id_attribute for this protocol.": "Không bắt buộc. Ghi đè remote_id_attribute trong keystone.conf cho protocol này.",
  "Optional. The hypervisor may still pick its own.": "Tùy chọn. Hypervisor vẫn có thể tự chọn tên khác.",
  "Optional. Users see it when launching; a host can be in only one zone.": "Không bắt buộc. Người dùng sẽ thấy khi khởi tạo máy ảo; một host chỉ có thể thuộc một vùng.",
  "Optional: an exact address from the pool (admins only). Empty picks the next free one.": "Tùy chọn: một địa chỉ chính xác trong pool (chỉ quản trị viên). Để trống sẽ chọn địa chỉ trống tiếp theo.",
  "Optional: certificate the load balancer presents to members.": "Tùy chọn: chứng chỉ mà load balancer xuất trình cho các thành viên.",
  "Optional: the listener sends its traffic here. Without one, the pool is used by L7 policies only.": "Tùy chọn: listener sẽ gửi lưu lượng tới đây. Nếu không chọn, pool chỉ được dùng bởi L7 policy.",
  "Optional; Keystone creates one when empty.": "Không bắt buộc; Keystone sẽ tạo một domain nếu để trống.",
