  "Projects and their role assignments are deleted. Servers, volumes and networks they own are not removed and become orphaned, so clean them up first. This can't be undone.": "Các dự án và gán vai trò của chúng sẽ bị xóa. Máy ảo, volume và mạng thuộc các dự án không bị xóa và sẽ trở thành tài nguyên mồ côi, vì vậy hãy dọn dẹp chúng trước. Không thể hoàn tác.",
  "Projects own cloud resources and quotas. Open a project to manage who can use it.": "Dự án sở hữu tài nguyên cloud và hạn mức. Mở một dự án để quản lý ai có thể sử dụng nó.",
  "Projects that never used object storage have no account yet and show 0.": "Các dự án chưa từng dùng lưu trữ đối tượng chưa có tài khoản và hiển thị 0.",
