  "Public SSH keys that Nova puts on new instances so you can log in. Key pairs belong to your user, in every project.": "Các khóa SSH công khai mà Nova đưa vào máy ảo mới để bạn có thể đăng nhập. Cặp khóa thuộc về người dùng của bạn, dùng được trong mọi dự án.",
