  "Role {name} updated": "Đã cập nhật vai trò {name}",
  "Role-based access control for Neutron objects: share a network, QoS policy or security group with chosen projects, without making it public. Admins can also share with every project or offer a network as external (for router gateways and floating IPs).": "Kiểm soát truy cập theo vai trò cho các đối tượng Neutron: chia sẻ mạng, chính sách QoS hoặc nhóm bảo mật với các dự án được chọn mà không cần công khai. Quản trị viên cũng có thể chia sẻ với mọi dự án hoặc cung cấp một mạng làm mạng bên ngoài (cho gateway của router và floating IP).",
  "Role-based access control for Neutron objects: share a network, QoS policy, security group, subnet pool or address scope with chosen projects, without making it public. Admins can also share with every project or offer a network as external (for router gateways and floating IPs).": "Kiểm soát truy cập theo vai trò cho các đối tượng Neutron: chia sẻ mạng, QoS policy, nhóm bảo mật, subnet pool hoặc address scope với các dự án được chọn mà không công khai. Quản trị viên còn có thể chia sẻ với mọi dự án hoặc cung cấp mạng làm mạng external (cho gateway của router và floating IP).",
