  "This container is empty.": "Container này trống.",
  "This flavor is public: every project can use it. Visibility is fixed at creation, so create a private copy to limit it to chosen projects.": "Flavor này công khai: mọi dự án đều có thể dùng. Phạm vi hiển thị được cố định khi tạo, vì vậy hãy tạo một bản riêng tư để giới hạn cho các dự án được chọn.",
