  "Volumes added to the group must use one of its volume types.": "Volume thêm vào nhóm phải dùng một trong các loại volume của nhóm.",
  "Volumes already created from it are not affected. This can't be undone.": "Các volume đã tạo từ nó không bị ảnh hưởng. Thao tác này không thể hoàn tác.",
  "Volumes already created from these snapshots are not affected. This can't be undone.": "Các volume đã tạo từ những snapshot này không bị ảnh hưởng. Thao tác này không thể hoàn tác.",
  "Volumes from this project waiting to be accepted by another project. The receiving project needs the transfer ID and the auth key, which is shown only when the transfer is created.": "Các volume của dự án này đang chờ dự án khác chấp nhận. Dự án nhận cần ID chuyển giao và khóa xác thực, khóa này chỉ hiển thị khi tạo chuyển giao.",
  "Volumes in {gName}": "Volume trong {gName}",
  "Volumes in error": "Volume bị lỗi",
  "Volumes managed as one unit. A group snapshot captures every volume at once (crash-consistent when the group type enables it), and a group can be cloned or rebuilt from a group snapshot.": "Các volume được quản lý như một đơn vị. Snapshot nhóm chụp mọi volume cùng lúc (nhất quán khi sự cố nếu loại nhóm bật tính năng này), và nhóm có thể được nhân bản hoặc dựng lại từ snapshot nhóm.",
  "Volumes of every project. Actions run with admin rights, so they work on other projects' volumes too.": "Volume của mọi dự án. Thao tác chạy với quyền quản trị nên cũng áp dụng được cho volume của dự án khác.",
  "Volumes of this type get the limits of the associated QoS specs. Front-end specs are applied by Nova on the hypervisor, back-end specs by the storage driver. Changes reach attached volumes on their next attach.": "Volume thuộc loại này nhận giới hạn của QoS specs được gắn. Specs front-end được Nova áp dụng trên hypervisor, specs back-end do driver lưu trữ áp dụng. Thay đổi có hiệu lực với volume đã gắn ở lần gắn tiếp theo.",
  "Volumes of type {join} that aren't in another group can join. Removing a volume keeps it.": "Volume thuộc loại {join} chưa nằm trong nhóm khác có thể tham gia. Gỡ volume khỏi nhóm vẫn giữ lại volume.",
