  "What the code refers to but doesn't manage (external networks, images, shared subnets…) is read with data sources instead of fixed IDs; a variable holds the ID when a name isn't unique.": "Những gì mã tham chiếu nhưng không quản lý (mạng ngoài, image, subnet dùng chung…) được đọc bằng data source thay vì ID cố định; khi tên không duy nhất, một biến (variable) giữ ID.",
