  "What users can choose when they create a load balancer (flavors and availability zones, backed by provider-specific profiles), and how many load balancer objects each project may have.": "Những gì người dùng có thể chọn khi tạo load balancer (flavor và vùng khả dụng, dựa trên các profile riêng của provider), và số lượng đối tượng load balancer mỗi dự án được có.",
  "Where and how the data is stored (replicas, erasure coding, SSD…). Can't be changed later.": "Dữ liệu được lưu ở đâu và như thế nào (bản sao, erasure coding, SSD…). Không thể thay đổi sau này.",
  "Where connections go when no L7 policy matches. Pools need a compatible protocol ({protocols}).": "Nơi kết nối được chuyển tới khi không có L7 policy nào khớp. Pool cần có giao thức tương thích ({protocols}).",
